import React from "react";
import Stack from "../Stack";
import Tooltip from "../Tooltip";
import Rating from "./Rating";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Rating> = {
  title: "Components/Rating",
  component: Rating,
  render: (args) => <Rating {...args} />
};

export default meta;
type Story = StoryObj<typeof Rating>;

export const Basic: Story = {
  tags: ["visual-test"],
};

export const Disabled: Story = {
  args: {
    disabled: true,
    defaultValue: 2.5
  },
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => (
    <Stack spacing="2-x">
      <Rating defaultValue={2.5} />
      <Rating disabled defaultValue={2.5} />
    </Stack>
  ),
};

export const Size: Story = {
  args: {
    size: "small",
    defaultValue: 2.5
  },
};

export const ReadOnly: Story = {
  args: {
    readOnly: true,
    value: 2.5
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [value, setValue] = React.useState(0);
    return (
      <>
        <Rating value={value} onChange={(val) => setValue(val)} />
        <p>Your vote: {value}/5</p>
      </>
    );
  },
};

export const Tooltips: Story = {
  args: {
    tooltips: ["bad", "poor", "ok", "good", "excellent"],
    defaultValue: 2.5
  },
};

export const Custom: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const RatingItemEmoji: React.FC<{
      children: React.ReactNode;
      isChecked: boolean;
      label: React.ReactNode;
    }> = ({ children, isChecked, label }) => (
      <Tooltip label={label} placement="top" offset={[0, 12]}>
        <div
          style={{
            fontSize: "2rem",
            opacity: isChecked ? 1 : 0.7,
          }}
        >
          {children}
        </div>
      </Tooltip>
    );

    const icons = ["😭", "😞", "😬", "🙂", "😁"];
    const labels = ["Crying", "Sad", "Smiling", "Happy", "Super Happy"];
    return (
      <Rating
        ariaLabel="Set your mood"
        getItemLabel={(index) => labels[index]}
        renderItem={({ index, ...rest }) => (
          <RatingItemEmoji {...rest} label={labels[index]}>
            {icons[index]}
          </RatingItemEmoji>
        )}
      />
    );
  },
};
